import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第55章 一整晚","description":"","frontmatter":{},"headers":[],"relativePath":"第55章_一整晚.md","filePath":"第55章_一整晚.md"}'),o={name:"第55章_一整晚.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第55章-一整晚" tabindex="-1">第55章 一整晚 <a class="header-anchor" href="#第55章-一整晚" aria-label="Permalink to &quot;第55章 一整晚&quot;">​</a></h1><p>她走前一天，八月十四号，那一晚她没睡。</p><p>她第二天下午的飞机，四点起飞。她那天晚上十一点上来，一直到我早上六点起床，她都在。</p><p>那七个多小时，她发给我的话，比前面一整年加起来都多。</p><p>我后来想，她那天不是睡不着。</p><p>她是知道自己以后说不成话了，所以那天晚上先说够。</p><p>一开始是正事。</p><p>她说，箱子封了三个，我那个小箱子没合上，拉链坏了一半。</p><p>她说，我妈给我塞了两件外套，她说那边冬天很冷。</p><p>她说，我说冬天冷我为什么不在这边穿。</p><p>她说，她说你到了就知道了。</p><p>她说，我什么都不知道。</p><p>我说，你到了会知道。</p><p>她说，你别替她说。</p><p>我说，我没替。</p><p>她说，你这个人，你连不替我说话的时候都在替。</p><p>我看到这句，愣了一下。</p><p>因为她讲得对，而我不知道怎么讲对的。</p><p>然后从十二点多开始，她讲了一些别的。</p><p>她先讲了她那个号。</p><p>她说，我跟你说一件事，我憋了三年。</p><p>我说，你说。</p><p>她说，我去年删那个号之前，我第一件事不是删东西。</p><p>她说，我先把你的备注改了。</p><p>她说，我改成三个字，很难看的三个字，你自己都猜不出来。</p><p>我说，为什么。</p><p>她说，因为我怕我删到一半舍不得。</p><p>她说，我怕我搜你的名字搜出来一句话，我就开始哭。</p><p>她说，我把你变成一个难看的词，我就删得下去了。</p><p>我坐在那儿，看着她这几行字。</p><p>我那时候十九岁。我第一次知道一件事：一个人要在删之前先把对方改丑。</p><p>我说，那你改成了什么。</p><p>她说，不告诉你。</p><p>我说，你不是说憋了三年。</p><p>她说，憋三年是指我要讲，不包括讲全。</p><p>她说，我讲一半，另一半我留着。</p><p>我说，留着干什么。</p><p>她隔了很久。</p><p>她说，留着证明我这一辈子也有过一个东西没交出去。</p><p>第二件事，她讲了那年冬天。</p><p>她说，我一直没问过你一件事。</p><p>我说，你问。</p><p>她说，高二那年冬天，你是不是来过我们这边的车站。</p><p>我的手指停在屏幕上。</p><p>我说，谁跟你说的。</p><p>她说，你那个同学。</p><p>她说，就那次你去找我同学，被认出来那次。</p><p>我说，他跟你讲了？</p><p>她说，他没跟我讲。</p><p>她说，是我后来看见你的。</p><p>她说，那天我在家里的窗边。</p><p>她说，我看见你从车站那边往回走，一个人，没拿包。</p><p>她说，那条路从车站走回我家，要经过一个超市，一个银行。</p><p>她说，你走得很慢。</p><p>她说，我看了你一路。</p><p>我说，你为什么不下来。</p><p>她说，我当时在跟我妈吵架。</p><p>她说，我那天哭得很难看。</p><p>她说，我要是下来，你看见我这个样子，你要难受一天。</p><p>我说，我那天已经难受一天了。</p><p>她说，我知道。</p><p>她说，我在上面看着你难受。</p><p>她说，我当时想，你别走这条路，你换一条。</p><p>她说，你没换。</p><p>我坐在床上，把那晚的每一步都记起来了。</p><p>我记得那条路，我记得银行门口在修，我把包换到另一只手。</p><p>我记得我走到超市门口站了一下，我以为没人。</p><p>我说，你为什么现在才说。</p><p>她说，因为我要是那时候说，你会觉得你那天白站了。</p><p>她说，你现在说，是想让我怎么办。</p><p>我看到最后这一句，手凉了。</p><p>她不是在问怎么办。</p><p>她这句话的意思是：你把它讲出来了，我这边就得给一个回应，而我给不出。</p><p>而她不给出的那部分，会变成我的新账。</p><p>我打了很多字。</p><p>我打的是：我没想让你怎么办。我只是那时候没上车。</p><p>我把&quot;没上车&quot;三个字删了。</p><p>我发出去的是：我没想让你怎么办。</p><p>她回：你想。</p><p>她回：你就是想我欠你一次。</p><p>她回：你算盘打得很好，你从来不吭声。</p><p>我那天晚上第一次跟她顶了一句。</p><p>我说，对。</p><p>我说，我就是想。</p><p>我说，我要你欠我一次。</p><p>我说，我知道你还不起，我就是想让你记着有人欠着。</p><p>她没回。</p><p>那一夜她第一次没回。</p><p>三点四十，屏幕上亮了一次。</p><p>她说，那你记住了。</p><p>她说，我这一辈子被人欠着的时候不多。</p><p>她说，我记着你。</p><p>三点四十一到早上六点，她又讲了两个小时。</p><p>讲她家那个阳台的缝，讲她妈半夜在客厅哭，讲她爸那年一年回来两次，讲她把小学生的东西全送了人，讲她留了一样东西没送，为什么留她不说。</p><p>我说，那你说留没留。</p><p>她说，留了。</p><p>我说，在哪儿。</p><p>她说，不在我身边。</p><p>我说，那在哪。</p><p>她说，以后告诉你。</p><p>三点多的时候，她忽然给我派了一件事。</p><p>她说，你帮我个忙。</p><p>我说，说。</p><p>她说，奶茶店旁边那棵树，很歪的那棵。</p><p>她说，你每年三月去站一下，看它还在不在。</p><p>我说，看它干什么。</p><p>她说，不干什么。</p><p>她说，我要是知道它还在，我就知道那条路还在。</p><p>她说，那条路在，我就当我还能回去。</p><p>我说，你自己不能去看？</p><p>她说，我回去都是住酒店。</p><p>她说，我住酒店的话，那我就不是回去。</p><p>我坐在那儿，看着这三行。</p><p>她要我在她那条路上，每年替她站一下。</p><p>这件事我做不到，因为我不在她那个城市。</p><p>但是我说，好。</p><p>她说，你别答应得快。</p><p>我说，我三月初去。</p><p>她说，你听不明白吗，我说的是每年。</p><p>我说，我听得明白。</p><p>我说，每年。</p><p>后来我把这一句拄进了本子。</p><p>拄完我在旁边写了一行：她把自己的眼睛存在了我这里。</p><p>写这一行的时候是凌晨，我在考虑一件事没考虑明白。</p><p>我给不了她一个回答，但我能给她一个不能拒绝的东西。</p><p>而一个不能拒绝的东西，在两个人之间是不平等的。</p><p>那天晚上我第一次怕她。</p><p>不是怕她冷。</p><p>是怕她把一个人安排进自己的日子里，而那个人完全不知道自己在往里走。</p><p>六点我起床。</p><p>我妈在客厅煮面。</p><p>我刷牙的时候手机又亮了一次。</p><p>她说，我醒了，我妈叫我起来吃早饭。</p><p>她说，我的箱子拉链还没修。</p><p>她说，我今天可能要迟到。</p><p>一夜七个多小时，她最后跟我讲的是拉链。</p><p>我把牙刷在嘴里，看着那三行字。</p><p>我没有把她那一夜的话记进本子。</p><p>那天早上我做了另一件事。</p><p>我把本子翻到最后，写了一行日期，写完合上。</p><p>我一个字也没抄。</p><p>因为那一夜的话，我一抄就要抄到天亮，抄完她就要上飞机了。</p><p>我那时候第一次知道，有些话是不能抄的。</p><p>你只能让它一整晚都在，然后第二天早上，它变成一条拉链。</p>',144)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
